do $$
declare v_count integer;
begin
  select count(*) into v_count
  from public.catalog_r2_serving_objects o
  join public.catalog_releases r on r.id=o.release_id
  where r.maker_slug='nissan' and r.is_current=true and r.published_at is not null
    and o.object_kind='diagram_image';
  if v_count <> 2348 then
    raise exception 'diagram image manifest count mismatch: expected 2348, got %', v_count;
  end if;
end $$;
